// @name Life counter
// @background #15181d
// @refresh 3600
// A table-top life counter for card and board games, with dice. Each player
// has a part of the board: tap its left half to lose a life, its right half to
// gain one, and hold (or tap the small -5 and +5) to change by five. The
// change since the last pause shows beside the life ("-3"). With the frame
// lying flat between the players, the top row reads from across the table.
// Dice opens a d6, two d6, a d20 and a coin; the last roll stays in the bar.
// The game is kept in the scene's state, so a restart keeps it.
//
// A frame's own buttons walk the board's buttons and press them (Next and
// Prev move, Action presses: a player's minus, then plus, then Dice and New
// game), as on every UI. On a keyboard: 1 to 4 picks a player, Up and Down
// change their life (with Shift by five), Left and Right pick the next one,
// R rolls the last die again, N asks for a new game.
import { layout, numberSize, parts } from './board'
import {
  addDelta, changeLife, coinSide, deltaText, describeRoll, KIND_LABELS, KINDS, newGame, nextDeltaEnd, noDeltas,
  playerNames, readDeltas, readGame, roll, rollTotal, shownDelta,
} from './logic'

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

// Each player's colors: the part of the board (bg), the life and signs (fg),
// the name, the -5 / +5 chips (soft: filled, else outlined), the pill the
// change since the last pause sits in, and the keyboard's pick (sel).
const THEMES = {
  color: {
    page: 'bg-[#15181d] text-white',
    muted: 'text-[#aab2bd]',
    button: 'bg-[#2b3038] text-white active:bg-[#3d444f]',
    card: 'bg-[#f8fafc] text-[#1e293b]',
    cardButton: 'bg-[#e2e8f0] text-[#1e293b] active:bg-[#cbd5e1]',
    primary: 'bg-[#2f6fb0] text-white active:bg-[#265d94]',
    cardMuted: 'text-[#64748b]',
    scrim: 'bg-black/60',
    press: 'active:bg-white/15',
    players: [
      { bg: '#1f4e79', fg: '#ffffff', name: '#c9dcf0', soft: '#2d6296', pill: '#0f2f4f', pillFg: '#ffffff', sel: '#fbbf24' },
      { bg: '#9c4234', fg: '#ffffff', name: '#f3d2cb', soft: '#b0564a', pill: '#5e231b', pillFg: '#ffffff', sel: '#fbbf24' },
      { bg: '#1f6b5f', fg: '#ffffff', name: '#c4e6df', soft: '#2f8072', pill: '#0f3f37', pillFg: '#ffffff', sel: '#fbbf24' },
      { bg: '#5d3f78', fg: '#ffffff', name: '#ddd0ea', soft: '#73548f', pill: '#38244a', pillFg: '#ffffff', sel: '#fbbf24' },
    ],
    pattern: null,
    die: { fill: '#ffffff', stroke: '#334155', pip: '#1e293b', d20: '#1f4e79', d20Fg: '#ffffff', coin: '#e0b33c', coinEdge: '#8a6a12', coinFg: '#3b2f0a' },
  },
  // Black and white: the players in solid black and white parts, as a
  // chessboard, so two neighbours never look alike.
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    card: 'bg-white text-black border-4 border-black',
    cardButton: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    cardMuted: 'text-black',
    scrim: '',
    press: '',
    players: [
      { bg: '#000000', fg: '#ffffff', name: '#ffffff', soft: '', pill: '#ffffff', pillFg: '#000000', sel: '#ffffff' },
      { bg: '#ffffff', fg: '#000000', name: '#000000', soft: '', pill: '#000000', pillFg: '#ffffff', sel: '#000000', border: '#000000' },
    ],
    pattern: { 2: [0, 1], 3: [0, 1, 0], 4: [0, 1, 1, 0] },
    die: { fill: '#ffffff', stroke: '#000000', pip: '#000000', d20: '#ffffff', d20Fg: '#000000', coin: '#ffffff', coinEdge: '#000000', coinFg: '#000000' },
  },
}

// Color e-paper (Spectra's six inks): the players in solid inks as the panel
// shows them (dither.nim's measured table), white words on blue, red and
// green and black ones on yellow, so nothing is dithered into confetti.
THEMES.inks = {
  ...THEMES.high,
  primary: 'bg-[#18539a] text-white',
  players: [
    { bg: '#18539a', fg: '#ffffff', name: '#ffffff', soft: '', pill: '#ffffff', pillFg: '#18539a', sel: '#ffffff' },
    { bg: '#6b1119', fg: '#ffffff', name: '#ffffff', soft: '', pill: '#ffffff', pillFg: '#6b1119', sel: '#ffffff' },
    { bg: '#2a5531', fg: '#ffffff', name: '#ffffff', soft: '', pill: '#ffffff', pillFg: '#2a5531', sel: '#ffffff' },
    { bg: '#c7bb00', fg: '#000000', name: '#000000', soft: '', pill: '#000000', pillFg: '#ffffff', sel: '#000000' },
  ],
  pattern: null,
  die: { ...THEMES.high.die, d20: '#18539a', d20Fg: '#ffffff', coin: '#c7bb00', coinFg: '#000000' },
}

const themeOf = (app) => {
  if (highContrast(app)) return THEMES.high
  if ((app.state.contrast || 'auto') === 'auto' && app.frame.paper === true) return THEMES.inks
  return THEMES.color
}

// A fast panel (an LCD) shows a press at once and draws again when the change
// on show is due to go; e-paper does neither, and holds have no meaning there
// (people hold until something shows), so it gets the -5 and +5 chips.
const isFast = (app) => app.frame.fast ?? !app.frame.paper

// The game and the settings the handlers need, as the last get() or onEvent
// read them.
let game = null
let deltas = noDeltas()
let players = 2
let pauseMs = 3000
let fastPanel = true

const setup = (app) => {
  players = Math.max(2, Math.min(4, Number(app.state.players) || 2))
  const start = Number(app.state.startingLife) || 20
  const kept = readGame(app.state.game, start)
  // A first game, or one the starting life setting started again: kept now.
  if (!app.state.game || Number(app.state.game.start) !== start) frameos.setState('game', kept)
  game = kept
  deltas = readDeltas(frameos.recall('deltas'))
  // On e-paper a tap takes a refresh to show, so taps a few seconds apart are
  // still one change.
  fastPanel = isFast(app)
  pauseMs = fastPanel ? 3000 : 8000
}

const save = () => frameos.setState('game', game)

// One player's life up or down. The keyboard's pick stays where it is; a tap
// puts it away.
const bump = (i, by) => {
  if (!game) return
  game = changeLife(game, i, by)
  save()
  deltas = addDelta(deltas, i, by, Date.now(), pauseMs)
  frameos.remember('deltas', deltas)
}
const tap = (i, by) => {
  frameos.remember('sel', -1)
  bump(i, by)
}
const openCard = (card) => frameos.remember('card', card)
const closeCard = () => frameos.remember('card', '')
// A roll: the result is kept at once; a fast panel tumbles the die for a
// moment before it shows it (ROLLING_MS), e-paper shows it in one picture.
const ROLLING_MS = 600
const rollDice = (kind) => {
  if (!game) return
  game = { ...game, roll: roll(kind) }
  save()
  frameos.remember('card', 'dice')
  frameos.remember('rolledAt', fastPanel ? Date.now() : 0)
}
const startOver = () => {
  if (!game) return
  game = newGame(game.start, game.roll)
  save()
  deltas = noDeltas()
  frameos.remember('deltas', deltas)
  frameos.remember('card', '')
  frameos.remember('sel', -1)
}

// One player's part of the board, drawn as an <svg> so it can be turned to
// face across the table, with its two halves (and the chips in them) as the
// places to press. Its numbers come from parts(): see board.ts.
const Player = memo(({ i, x, y, w, h, ix, iy, iw, ih, turned, life, delta, name, look, t, unit, chips, tight, live, fast, sel, radius }) => {
  const c = t.players[look]
  const p = parts(iw, ih, unit, chips, tight)
  const ax = ix + iw / 2
  const ay = iy + ih / 2
  const text = String(life)
  const F = numberSize(p, text)
  const nameMax = Math.max(4, Math.floor((iw - 2 * p.pad) / (p.nameF * 0.56)))
  const label = name.length > nameMax ? `${name.slice(0, nameMax - 1)}.` : name
  const sy = ay + p.numY
  const half = p.stroke / 2
  const line = Math.max(3, Math.round(4 * unit))
  // A chip: -5 at the reader's bottom left, +5 at the bottom right.
  const chip = (dir) => {
    const cx = ax + dir * p.chipX
    const cy = ay + p.chipY
    return (
      <g>
        <rect x={cx - p.chipW / 2} y={cy - p.chipH / 2} width={p.chipW} height={p.chipH} rx={p.chipH / 2}
          fill={c.soft || 'none'} stroke={c.soft ? 'none' : c.fg} strokeWidth={c.soft ? 0 : Math.max(2, Math.round(2 * unit))} />
        <text x={cx} y={cy} fontSize={Math.round(p.chipH * 0.5)} fontWeight="bold" textAnchor="middle" dominantBaseline="central" fill={c.fg}>
          {dir < 0 ? '-5' : '+5'}
        </text>
      </g>
    )
  }
  const pill = delta ? deltaText(delta) : ''
  const pillW = Math.round(p.deltaF * (0.62 * pill.length + 0.9))
  // Where the reader's minus half is on the screen: their left, which is our
  // right when they sit across the table.
  const minusAt = turned ? 'right' : 'left'
  // The halves stand in from the edge a little, so the keys' bracket shows
  // inside a part with a border of its own.
  const m = Math.max(3, Math.round(4 * unit))
  const zone = (side, by) => {
    const left = side === 'left'
    const zx = left ? m : Math.round(ax)
    const zw = left ? Math.round(ax) - m : w - m - Math.round(ax)
    // The chip in this half, from the zone's corner: turned with the player.
    let hit = null
    if (p.chips) {
      const rx = ax + (by < 0 ? -1 : 1) * p.chipX
      const ry = ay + p.chipY
      const sx = turned ? 2 * ax - rx : rx
      const syy = turned ? 2 * ay - ry : ry
      const hw = p.chipW / 2 + 6, hh = p.chipH / 2 + 6
      hit = { x: Math.round(sx - hw - zx), y: Math.round(syy - hh - m), w: Math.round(2 * hw), h: Math.round(2 * hh) }
    }
    // The frame's keys ring what they are on in a color that shows on this
    // player's part (the runtime's own ring is black on e-paper), a half as a
    // bracket open towards the middle so it never crosses the life.
    const focus = `focus:border-[${Math.max(3, Math.round(4 * unit))}px] focus:border-[${c.sel}]`
    return (
      <div className={`absolute left-[${zx}px] top-[${m}px] w-[${zw}px] h-[${h - 2 * m}px] ${left ? `rounded-l-[${Math.max(0, radius - m)}px]` : `rounded-r-[${Math.max(0, radius - m)}px]`} ${fast ? t.press : ''} ${focus} ${left ? 'focus:border-r-0' : 'focus:border-l-0'}`}
        title={`${name}: ${by < 0 ? 'minus' : 'plus'} one`}
        onClick={() => tap(i, by)}
        onLongPress={fast ? () => tap(i, by * 5) : undefined}>
        {hit ? (
          <div className={`absolute left-[${hit.x}px] top-[${hit.y}px] w-[${hit.w}px] h-[${hit.h}px] rounded-full ${focus}`}
            title={`${name}: ${by < 0 ? 'minus' : 'plus'} five`}
            onClick={() => tap(i, by * 5)} />
        ) : null}
      </div>
    )
  }
  return (
    <div className={`absolute left-[${x}px] top-[${y}px] w-[${w}px] h-[${h}px]`}>
      <svg className={`absolute left-0 top-0 w-[${w}px] h-[${h}px]`} viewBox={`0 0 ${w} ${h}`}>
        <rect x={c.border ? line / 2 : 0} y={c.border ? line / 2 : 0} width={c.border ? w - line : w} height={c.border ? h - line : h}
          rx={radius} fill={c.bg} stroke={c.border || 'none'} strokeWidth={c.border ? line : 0} />
        {sel ? (
          <rect x={line * 1.5} y={line * 1.5} width={w - line * 3} height={h - line * 3} rx={Math.max(0, radius - line)}
            fill="none" stroke={c.sel} strokeWidth={line} />
        ) : null}
        <g transform={`rotate(${turned ? 180 : 0} ${ax} ${ay})`}>
          <text x={ax} y={ay + p.nameY} fontSize={p.nameF} textAnchor="middle" dominantBaseline="central" fill={c.name}>{label}</text>
          <text x={ax} y={sy} fontSize={F} textAnchor="middle" dominantBaseline="central" fill={c.fg} stroke={c.fg} strokeWidth={Math.max(1, Math.round(F * 0.03))} strokeLinejoin="round">{text}</text>
          <rect x={ax - p.signX - p.sign / 2} y={sy - half} width={p.sign} height={p.stroke} rx={half} fill={c.fg} />
          <rect x={ax + p.signX - p.sign / 2} y={sy - half} width={p.sign} height={p.stroke} rx={half} fill={c.fg} />
          <rect x={ax + p.signX - half} y={sy - p.sign / 2} width={p.stroke} height={p.sign} rx={half} fill={c.fg} />
          {p.chips ? chip(-1) : null}
          {p.chips ? chip(1) : null}
          {pill ? (
            <g>
              <rect x={ax - pillW / 2} y={ay + p.deltaY - p.deltaF * 0.65} width={pillW} height={Math.round(p.deltaF * 1.3)}
                rx={Math.round(p.deltaF * 0.65)} fill={c.pill} />
              <text x={ax} y={ay + p.deltaY} fontSize={p.deltaF} fontWeight="bold" textAnchor="middle" dominantBaseline="central" fill={c.pillFg}>{pill}</text>
            </g>
          ) : null}
        </g>
      </svg>
      {live ? zone(minusAt, -1) : null}
      {live ? zone(minusAt === 'left' ? 'right' : 'left', 1) : null}
    </div>
  )
})

const Die = ({ px }) => (
  <svg className={`w-[${px}px] h-[${px}px]`} viewBox="0 0 24 24">
    <rect x="3" y="3" width="18" height="18" rx="4" fill="none" stroke="currentColor" strokeWidth="2" />
    <circle cx="8.5" cy="8.5" r="1.7" fill="currentColor" />
    <circle cx="12" cy="12" r="1.7" fill="currentColor" />
    <circle cx="15.5" cy="15.5" r="1.7" fill="currentColor" />
  </svg>
)

// The bar between the rows (or under them): New game, the last roll, Dice.
const Bar = memo(({ x, y, w, h, t, unit, small, live, words }) => {
  const f = Math.round((small ? 14 : 17) * unit)
  const bh = h - Math.round((small ? 8 : 10) * unit)
  const btn = `h-[${bh}px] px-[${Math.round((small ? 10 : 16) * unit)}px] rounded-[${Math.round(12 * unit)}px] flex items-center gap-[${Math.round(6 * unit)}px] text-[${f}px] font-semibold ${t.button}`
  return (
    <div className={`absolute left-[${x}px] top-[${y}px] w-[${w}px] h-[${h}px] flex items-center gap-[${Math.round(8 * unit)}px]`}>
      <div className={btn} onClick={live ? () => openCard('reset') : undefined}>{small ? 'Reset' : 'New game'}</div>
      <span className={`flex-1 min-w-0 text-center truncate text-[${f}px] ${t.muted}`}>{words}</span>
      <div className={btn} onClick={live ? () => openCard('dice') : undefined}>
        <Die px={Math.round(f * 1.25)} />
        <span>Dice</span>
      </div>
    </div>
  )
})

// The pips of a d6 face, on a 0..1 square.
const PIPS = {
  1: [[0.5, 0.5]],
  2: [[0.27, 0.27], [0.73, 0.73]],
  3: [[0.27, 0.27], [0.5, 0.5], [0.73, 0.73]],
  4: [[0.27, 0.27], [0.73, 0.27], [0.27, 0.73], [0.73, 0.73]],
  5: [[0.27, 0.27], [0.73, 0.27], [0.5, 0.5], [0.27, 0.73], [0.73, 0.73]],
  6: [[0.27, 0.25], [0.73, 0.25], [0.27, 0.5], [0.73, 0.5], [0.27, 0.75], [0.73, 0.75]],
}

// A d6 face: its edge as a filled square under a smaller one (a stroked
// rounded square left notches at its corners).
const face = (d, x, y, s, v, line) => (
  <g>
    <rect x={x} y={y} width={s} height={s} rx={s * 0.16} fill={d.stroke} />
    <rect x={x + line} y={y + line} width={s - 2 * line} height={s - 2 * line} rx={s * 0.16 - line} fill={d.fill} />
    {(PIPS[v] || []).map(([px, py]) => <circle cx={x + px * s} cy={y + py * s} r={s * 0.085} fill={d.pip} />)}
  </g>
)

// The last roll as a picture, w by h.
const RollPicture = ({ r, w, h, t, unit }) => {
  const d = t.die
  const line = Math.max(2, Math.round(3 * unit))
  const cx = w / 2, cy = h / 2
  let body = null
  if (!r) {
    const s = h * 0.8
    body = (
      <g>
        {face(d, cx - s / 2, cy - s / 2, s, 0, line)}
        <text x={cx} y={cy} fontSize={s * 0.5} fontWeight="bold" textAnchor="middle" dominantBaseline="central" fill={d.stroke}>?</text>
      </g>
    )
  } else if (r.kind === 'd6') {
    const s = h * 0.86
    body = face(d, cx - s / 2, cy - s / 2, s, r.values[0], line)
  } else if (r.kind === '2d6') {
    const s = Math.min(h * 0.82, (w - h * 0.2) / 2.2)
    const g = s * 0.2
    body = (
      <g>
        {face(d, cx - s - g / 2, cy - s / 2, s, r.values[0], line)}
        {face(d, cx + g / 2, cy - s / 2, s, r.values[1], line)}
      </g>
    )
  } else if (r.kind === 'd20') {
    // A d20 seen face on: a hexagon around the triangle with the number.
    const R = h * 0.48
    const pts = [0, 1, 2, 3, 4, 5].map((k) => {
      const a = (Math.PI / 3) * k - Math.PI / 2
      return `${(cx + R * Math.cos(a)).toFixed(1)},${(cy + R * Math.sin(a)).toFixed(1)}`
    })
    const tri = [0, 2, 4].map((k) => pts[k]).join(' ')
    body = (
      <g>
        <polygon points={pts.join(' ')} fill={d.d20} stroke={d.stroke} strokeWidth={line} strokeLinejoin="round" />
        <polygon points={tri} fill="none" stroke={d.d20Fg} strokeWidth={Math.max(1, line - 1)} strokeLinejoin="round" />
        <text x={cx} y={cy + R * 0.12} fontSize={R * 0.62} fontWeight="bold" textAnchor="middle" dominantBaseline="central" fill={d.d20Fg}>
          {String(r.values[0])}
        </text>
      </g>
    )
  } else {
    const R = h * 0.46
    body = (
      <g>
        <circle cx={cx} cy={cy} r={R} fill={d.coin} stroke={d.coinEdge} strokeWidth={line} />
        <circle cx={cx} cy={cy} r={R * 0.82} fill="none" stroke={d.coinEdge} strokeWidth={Math.max(1, line - 1)} />
        <text x={cx} y={cy} fontSize={R * 0.36} fontWeight="bold" textAnchor="middle" dominantBaseline="central" fill={d.coinFg}>
          {coinSide(r.values[0])}
        </text>
      </g>
    )
  }
  return (
    <svg className={`w-[${w}px] h-[${h}px]`} viewBox={`0 0 ${w} ${h}`}>
      {body}
    </svg>
  )
}

// A card over the board, in the middle of the panel (of the square inside the
// circle on a round one). The board under it takes no presses while it shows.
const Card = ({ W, H, t, w, children, pad }) => (
  <div className={`absolute left-0 top-0 w-[${W}px] h-[${H}px] flex items-center justify-center ${t.scrim}`}>
    <div className={`w-[${w}px] rounded-[${Math.round(pad * 1.2)}px] p-[${pad}px] flex flex-col gap-[${Math.round(pad * 0.7)}px] ${t.card}`}>
      {children}
    </div>
  </div>
)

// A button on a card; `tight`: one of the four dice, as wide as its column.
const cardButton = (cls, f, h, onClick, words, tight = false) => (
  <div className={`h-[${h}px] px-[${tight ? 2 : Math.round(h * 0.35)}px] rounded-[${Math.round(h * 0.25)}px] flex items-center justify-center text-[${f}px] font-semibold ${cls}`}
    onClick={onClick}>
    {words}
  </div>
)

const diceCard = (t, W, H, room, unit, small, r, rolling) => {
  const pad = Math.round((small ? 10 : 16) * unit)
  const f = Math.round((small ? 14 : 18) * unit)
  const bh = Math.round((small ? 36 : 46) * unit)
  const titleF = Math.round((small ? 18 : 24) * unit)
  const w = Math.min(room.w, Math.round(520 * unit))
  // The picture takes what the card leaves of the height it may have.
  const fixed = 2 * pad + bh + Math.round(f * 1.5) + bh + 3 * Math.round(pad * 0.7)
  const ph = Math.max(40, Math.min(Math.round(170 * unit), room.h - fixed, Math.round((w - 2 * pad) * 0.5)))
  return (
    <Card W={W} H={H} t={t} w={w} pad={pad}>
      <div className="flex items-center justify-between">
        <span className={`text-[${titleF}px] font-bold`}>Dice</span>
        {cardButton(t.cardButton, f, bh, closeCard, 'Close')}
      </div>
      <div className="flex justify-center">
        <RollPicture r={r} w={w - 2 * pad} h={ph} t={t} unit={unit} />
      </div>
      <span className={`text-[${f}px] text-center truncate ${r && !rolling ? 'font-semibold' : t.cardMuted}`}>
        {rolling ? 'Rolling...' : r ? (r.kind === '2d6' ? `${r.values[0]} + ${r.values[1]} = ${rollTotal(r)}` : r.kind === 'coin' ? coinSide(r.values[0]) : `${KIND_LABELS[r.kind]}: ${r.values[0]}`) : 'Pick what to roll'}
      </span>
      <div className={`grid grid-cols-4 gap-[${Math.round(pad * 0.5)}px]`}>
        {KINDS.map((kind) => cardButton(r && r.kind === kind ? t.primary : t.cardButton, f, bh, () => rollDice(kind), KIND_LABELS[kind], true))}
      </div>
    </Card>
  )
}

const resetCard = (t, W, H, room, unit, small) => {
  const pad = Math.round((small ? 10 : 16) * unit)
  const f = Math.round((small ? 14 : 18) * unit)
  const bh = Math.round((small ? 36 : 46) * unit)
  const titleF = Math.round((small ? 18 : 24) * unit)
  const w = Math.min(room.w, Math.round(420 * unit))
  return (
    <Card W={W} H={H} t={t} w={w} pad={pad}>
      <span className={`text-[${titleF}px] font-bold`}>New game?</span>
      <span className={`text-[${f}px] ${t.cardMuted}`}>{`Everyone goes back to ${game.start} life.`}</span>
      <div className={`flex justify-end gap-[${Math.round(pad * 0.6)}px]`}>
        {cardButton(t.cardButton, f, bh, closeCard, 'Cancel')}
        {cardButton(t.primary, f, bh, startOver, 'New game')}
      </div>
    </Card>
  )
}

// A keyboard's keys (on a Pi, in the preview). The frame's Back closes a card.
export function onEvent(app, context) {
  setup(app)
  const card = frameos.recall('card') || ''
  if (context.event === 'back') {
    if (!card) return false
    closeCard()
    return true
  }
  if (context.event !== 'keyDown') return false
  const p = context.payload || {}
  if (p.ctrl || p.alt || p.meta) return false
  const key = String(p.key || '')
  const again = () => rollDice(game.roll ? game.roll.kind : 'd20')
  if (card === 'reset') {
    if (key === 'Enter' || key === 'y') startOver()
    else if (key === 'Escape' || key === 'n') closeCard()
    else return false
    return true
  }
  if (card === 'dice') {
    if (key === 'Escape') closeCard()
    else if (key === 'r') again()
    else return false
    return true
  }
  const sel = frameos.recall('sel') ?? -1
  if (key >= '1' && key <= '4' && key.length === 1) {
    if (Number(key) > players) return false
    frameos.remember('sel', Number(key) - 1)
    return true
  }
  if (key === 'ArrowLeft' || key === 'ArrowRight') {
    const step = key === 'ArrowRight' ? 1 : players - 1
    frameos.remember('sel', sel < 0 ? 0 : (sel + step) % players)
    return true
  }
  const arrow = key === 'ArrowUp' ? 1 : key === 'ArrowDown' ? -1 : 0
  const by = arrow ? arrow * (p.shift ? 5 : 1) : key === '+' || key === '=' ? 1 : key === '-' || key === '_' ? -1 : 0
  if (by) {
    const i = sel >= 0 && sel < players ? sel : 0
    frameos.remember('sel', i)
    bump(i, by)
    return true
  }
  if (key === 'r') {
    again()
    return true
  }
  if (key === 'n') {
    openCard('reset')
    return true
  }
  if (key === 'Escape' && sel >= 0) {
    frameos.remember('sel', -1)
    return true
  }
  return false
}

export function get(app, context) {
  setup(app)
  const t = themeOf(app)
  const fast = isFast(app)
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const round = context?.round === true
  const now = Date.now()
  // The change on show goes after a pause: on a fast panel the frame draws
  // again then. E-paper keeps it until its next picture, which the next tap
  // or the hour brings.
  let wait = nextDeltaEnd(deltas, now, pauseMs, players)
  if (wait >= 0) wait = Math.max(0.2, wait + 0.05)
  const card = frameos.recall('card') || ''
  // A die tumbling: a face at random each frame, about 12 a second, worked
  // out from the clock, until it lands on the roll that was kept.
  const rolling = fast && card === 'dice' && !!game.roll && now - (frameos.recall('rolledAt') || 0) < ROLLING_MS
  if (rolling) wait = 0.08
  if (fast && wait >= 0) frameos.setNextSleep(wait)
  const shownRoll = rolling ? roll(game.roll.kind) : game.roll
  // A watch or a 2.8" panel: smaller type and bar. A panel of 900 px or more
  // on its shorter side at render scale 1 (a 13.3" e-paper): larger, by halves.
  const small = Math.min(W, H) < 320
  const unit = Math.min(W, H) >= 900 ? Math.min(3, Math.floor((Math.min(W, H) / 480) * 2) / 2) : 1
  const facing = app.state.facing === 'upright' ? 'upright' : 'across'
  const b = layout(W, H, players, facing, round, unit, small)
  const names = playerNames(app.state.names, players)
  const sel = card ? -1 : frameos.recall('sel') ?? -1
  const live = !card
  // The middle of the bar: the last roll, else how to change by five.
  const hint = fast ? (small || round ? 'Hold for 5' : 'Hold to change by 5') : ''
  const words = rolling ? '' : describeRoll(game.roll) || hint
  // What a card may cover: the panel less a margin, or the square inside the
  // circle.
  const side = Math.floor((Math.min(W, H) / 2 - 12) * Math.SQRT2)
  const margin = Math.round((small ? 8 : 16) * unit)
  const room = round ? { w: side, h: side } : { w: W - 2 * margin, h: H - 2 * margin }
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      {b.cells.map((cell) => (
        <Player key={cell.i} i={cell.i} x={cell.x} y={cell.y} w={cell.w} h={cell.h}
          ix={cell.inner.x} iy={cell.inner.y} iw={cell.inner.w} ih={cell.inner.h}
          turned={cell.turned} life={game.life[cell.i]} delta={shownDelta(deltas, cell.i, now, pauseMs)}
          name={names[cell.i]} look={t.pattern ? t.pattern[players][cell.i] : cell.i} t={t} unit={unit}
          chips={!round} tight={round} live={live} fast={fast} sel={sel === cell.i} radius={b.radius} />
      ))}
      <Bar x={b.bar.x + b.barInner.x} y={b.bar.y} w={b.barInner.w} h={b.bar.h} t={t} unit={unit} small={small || round}
        live={live} words={words} />
      {card === 'dice' ? diceCard(t, W, H, room, unit, small || round, shownRoll, rolling) : null}
      {card === 'reset' ? resetCard(t, W, H, room, unit, small || round) : null}
    </div>
  )
}

