// The game itself, without any drawing: life totals, the change since the
// last pause, the dice, and which players read from across the table. Kept
// small: the whole game is a few numbers in the scene's state.

export const MAX_PLAYERS = 4
// Life never runs past this either way (a drawn-out game of infinite combos
// still fits on the screen).
export const LIMIT = 999

export type Roll = { kind: string; values: number[] }
export type Game = { start: number; life: number[]; roll: Roll | null }

export const KINDS = ['d6', '2d6', 'd20', 'coin']
export const KIND_LABELS = { d6: 'd6', '2d6': '2d6', d20: 'd20', coin: 'Coin' }

const clampLife = (v: number) => Math.max(-LIMIT, Math.min(LIMIT, v))

// A fresh game: everyone at the starting life. The last roll stays.
export function newGame(start: number, roll: Roll | null = null): Game {
  const life = []
  for (let i = 0; i < MAX_PLAYERS; i++) life.push(start)
  return { start, life, roll }
}

const validRoll = (roll): Roll | null => {
  if (!roll || typeof roll !== 'object' || KINDS.indexOf(roll.kind) < 0 || !Array.isArray(roll.values)) return null
  const values = roll.values.map((v) => Math.round(Number(v))).filter((v) => Number.isFinite(v))
  return values.length ? { kind: roll.kind, values } : null
}

// The game kept in the scene's state, or a new one. A game begun at another
// starting life (the setting was changed: a Commander game at 40, say) starts
// again at the new one.
export function readGame(saved, start: number): Game {
  if (!saved || typeof saved !== 'object' || !Array.isArray(saved.life)) return newGame(start)
  const roll = validRoll(saved.roll)
  if (Number(saved.start) !== start) return newGame(start, roll)
  const life = []
  for (let i = 0; i < MAX_PLAYERS; i++) {
    const v = Number(saved.life[i])
    life.push(Number.isFinite(v) ? clampLife(Math.round(v)) : start)
  }
  return { start, life, roll }
}

// One player's life up or down by `by`.
export function changeLife(game: Game, i: number, by: number): Game {
  if (i < 0 || i >= MAX_PLAYERS) return game
  const life = game.life.slice()
  life[i] = clampLife(life[i] + by)
  return { ...game, life }
}

// The change since the last pause, per player: taps that come within
// `pauseMs` of each other add up ("-3"), and the next tap after a pause
// starts again from nothing. `at` is when each last changed.
export type Deltas = { d: number[]; at: number[] }
export const noDeltas = (): Deltas => ({ d: [0, 0, 0, 0], at: [0, 0, 0, 0] })

export function readDeltas(kept): Deltas {
  if (!kept || !Array.isArray(kept.d) || !Array.isArray(kept.at)) return noDeltas()
  const d = [], at = []
  for (let i = 0; i < MAX_PLAYERS; i++) {
    d.push(Number(kept.d[i]) || 0)
    at.push(Number(kept.at[i]) || 0)
  }
  return { d, at }
}

export function addDelta(deltas: Deltas, i: number, by: number, now: number, pauseMs: number): Deltas {
  const d = deltas.d.slice(), at = deltas.at.slice()
  const paused = now - at[i] >= pauseMs
  d[i] = (paused ? 0 : d[i]) + by
  at[i] = now
  return { d, at }
}

// The change to show beside a player's life now: 0 once they paused.
export function shownDelta(deltas: Deltas, i: number, now: number, pauseMs: number): number {
  return now - deltas.at[i] < pauseMs ? deltas.d[i] : 0
}

// Seconds until the first change on show is due to go, or -1 with none on show.
export function nextDeltaEnd(deltas: Deltas, now: number, pauseMs: number, players: number): number {
  let soonest = -1
  for (let i = 0; i < players; i++) {
    if (!shownDelta(deltas, i, now, pauseMs)) continue
    const left = (pauseMs - (now - deltas.at[i])) / 1000
    if (soonest < 0 || left < soonest) soonest = left
  }
  return soonest
}

export const deltaText = (d: number) => (d > 0 ? `+${d}` : `${d}`)

// A roll of the dice. `random` is Math.random, in [0, 1).
export function roll(kind: string, random: () => number = Math.random): Roll {
  const die = (sides: number) => Math.min(sides, 1 + Math.floor(random() * sides))
  if (kind === '2d6') return { kind, values: [die(6), die(6)] }
  if (kind === 'd20') return { kind, values: [die(20)] }
  // A coin: 1 is heads, 2 tails.
  if (kind === 'coin') return { kind, values: [die(2)] }
  return { kind: 'd6', values: [die(6)] }
}

export const rollTotal = (r: Roll) => r.values.reduce((sum, v) => sum + v, 0)

export const coinSide = (v: number) => (v === 1 ? 'Heads' : 'Tails')

// The last roll in a few words, for the bar: "d20: 17", "2d6: 3 + 5 = 8".
export function describeRoll(r: Roll | null): string {
  if (!r) return ''
  if (r.kind === 'coin') return `Coin: ${coinSide(r.values[0])}`
  if (r.kind === '2d6') return `2d6: ${r.values[0]} + ${r.values[1]} = ${rollTotal(r)}`
  return `${r.kind}: ${r.values[0]}`
}

// Which way the players sit. "across": the frame lies flat between them, and
// the top row is turned to read from the far side of the table.
export function rowsOf(players: number, landscape: boolean, facing: string, round: boolean) {
  const all = []
  for (let i = 0; i < players; i++) all.push(i)
  const split = Math.floor(players / 2)
  if (facing === 'across' || round) return { rows: [all.slice(0, split), all.slice(split)], barAfter: 0 }
  if (players === 4) return { rows: [[0, 1], [2, 3]], barAfter: 0 }
  // Everyone reads from the bottom: side by side on a wide panel, stacked on
  // a tall one, the buttons between two rows or under three.
  if (landscape) return { rows: [all], barAfter: -1 }
  return { rows: all.map((i) => [i]), barAfter: players === 2 ? 0 : -1 }
}

export function isTurned(i: number, players: number, facing: string): boolean {
  return facing === 'across' && i < Math.floor(players / 2)
}

// The names from the setting ("Ana, Ben"), "Player 3" where none is given.
export function playerNames(text, players: number): string[] {
  const given = String(text || '').split(',').map((s) => s.trim())
  const names = []
  for (let i = 0; i < players; i++) names.push(given[i] ? given[i].slice(0, 24) : `Player ${i + 1}`)
  return names
}

