// Where everything goes, worked out from the canvas: each player's part of
// the board, the bar of buttons, and inside each part where the name, the
// life, the minus and plus signs and the change since the last pause sit.
// Pure numbers, so every panel (a round one too) gets a board that fills it.
import { isTurned, rowsOf } from './logic'

export type Box = { x: number; y: number; w: number; h: number }
// `inner`: the part of the cell the content goes in, from its corner: the
// whole cell, or on a round panel the largest box of it inside the circle.
export type Cell = Box & { i: number; turned: boolean; inner: Box }
export type Board = { cells: Cell[]; bar: Box; barInner: Box; radius: number }

const r = Math.round

// The box inside the circle (centre cx, cy, radius rad) and the cell where
// the life can be drawn largest, against the cell's edge nearest the centre
// line (its bottom in the top row, its top in the bottom row): low and wide
// near the middle, or taller and narrower towards the rim.
function insideCircle(cell: Box, cx: number, cy: number, rad: number, top: boolean, unit: number): Box {
  const near = top ? cell.y + cell.h : cell.y
  const dyNear = Math.abs(near - cy)
  let best = { x: 0, y: 0, w: 0, h: 0 }
  let bestScore = -1
  for (let step = 1; step <= 48; step++) {
    const h = (cell.h * step) / 48
    const dyFar = dyNear + h
    if (dyFar >= rad) break
    const half = Math.sqrt(rad * rad - dyFar * dyFar)
    // Clear of a neighbour's edge too, so two lives side by side never read
    // as one row.
    const x1 = Math.max(cell.x + 8 * unit, cx - half)
    const x2 = Math.min(cell.x + cell.w - 8 * unit, cx + half)
    const w = x2 - x1
    if (w <= 0) continue
    // How big "20" would be, and the area for a tie.
    const score = numberSize(parts(w, h, unit, false, true), '20') * 100000 + w * h
    if (score > bestScore) {
      bestScore = score
      best = { x: x1 - cell.x, y: top ? cell.h - h : 0, w, h }
    }
  }
  return { x: r(best.x), y: r(best.y), w: r(best.w), h: r(best.h) }
}

// `unit`: 1 on a panel laid out for about 480 px on its shorter side, more on
// a big one. `small`: a watch or a 2.8" panel, under 320 px.
export function layout(W: number, H: number, players: number, facing: string, round: boolean, unit: number, small: boolean): Board {
  const { rows, barAfter } = rowsOf(players, W >= H, facing, round)
  const pad = round ? 0 : r((small ? 6 : 8) * unit)
  const gap = r((small ? 6 : 8) * unit)
  const barH = r((small ? 44 : 56) * unit)
  // Between the rows and the bar: one gap fewer than there are rows and bar.
  const rowH = (H - 2 * pad - barH - gap * rows.length) / rows.length
  const cells: Cell[] = []
  let bar: Box = { x: pad, y: H - pad - barH, w: W - 2 * pad, h: barH }
  let y = pad
  rows.forEach((row, ri) => {
    const cw = (W - 2 * pad - gap * (row.length - 1)) / row.length
    row.forEach((i, ci) => {
      const x = pad + ci * (cw + gap)
      const box = { x: r(x), y: r(y), w: r(x + cw) - r(x), h: r(y + rowH) - r(y) }
      cells.push({ ...box, i, turned: isTurned(i, players, facing), inner: { x: 0, y: 0, w: box.w, h: box.h } })
    })
    y += rowH + gap
    if (ri === barAfter) {
      bar = { x: pad, y: r(y), w: W - 2 * pad, h: barH }
      y += barH + gap
    }
  })
  let barInner = { x: 0, y: 0, w: bar.w, h: bar.h }
  if (round) {
    // Keep what is drawn 12 px in from the rim: the bezel covers the edge.
    const cx = W / 2, cy = H / 2, rad = Math.min(W, H) / 2 - 12
    cells.forEach((cell) => {
      cell.inner = insideCircle(cell, cx, cy, rad, cell.y + cell.h / 2 < cy, unit)
    })
    const dy = Math.max(Math.abs(bar.y - cy), Math.abs(bar.y + bar.h - cy))
    const half = Math.floor(Math.sqrt(Math.max(0, rad * rad - dy * dy)))
    barInner = { x: r(cx - half - bar.x), y: 0, w: 2 * half, h: bar.h }
  }
  return { cells, bar, barInner, radius: round ? 0 : r((small ? 10 : 16) * unit) }
}

// Inside a player's part: sizes and offsets from the middle of its inner box,
// as the player reading it sees them (y down from their side). `chips`: room
// for the small -5 and +5 buttons at the bottom corners. `tight`: a box
// inside the circle of a round panel, far from the edges the keys ring.
export type Parts = {
  pad: number
  nameF: number; nameY: number
  numY: number; numMax: number; numW: number
  sign: number; signX: number; stroke: number
  chips: boolean; chipW: number; chipH: number; chipX: number; chipY: number
  deltaF: number; deltaY: number
}

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

export function parts(w: number, h: number, unit: number, chipsWanted: boolean, tight = false): Parts {
  // At least clear of the bracket the frame's keys draw inside the edge.
  const pad = tight ? clamp(Math.min(w, h) * 0.04, 4, 10 * unit) : clamp(Math.min(w, h) * 0.05, 10 * unit, 16 * unit)
  const nameF = clamp(h * 0.11, 12, 22 * unit)
  const chips = chipsWanted && h >= 110 * unit && w >= 190 * unit
  const chipH = chips ? clamp(Math.min(h * 0.17, w * 0.11), 22, 40 * unit) : 0
  const chipW = chips ? r(chipH * 1.6) : 0
  const deltaF = chips ? r(chipH * 0.72) : clamp(h * 0.12, 12, 30 * unit)
  const top = pad + nameF * 1.25
  const bottom = chips ? pad + chipH : pad + deltaF * 1.3
  const zone = Math.max(10, h - top - bottom)
  // The minus and plus signs, either side of the life, as big as the zone
  // between the name and the bottom row lets them be.
  const sign = r(clamp(Math.min(zone * 0.45, w * 0.13), 14, 56 * unit))
  const side = pad + sign + Math.max(4, sign * 0.35)
  return {
    pad: r(pad),
    nameF: r(nameF), nameY: r(-h / 2 + pad + nameF * 0.55),
    numY: r((top - bottom) / 2), numMax: r(zone * 1.18), numW: r(w - 2 * side),
    sign, signX: r(w / 2 - pad - sign / 2), stroke: Math.max(3, r(sign * 0.2)),
    chips, chipW, chipH: r(chipH), chipX: r(w / 2 - pad - chipW / 2), chipY: r(h / 2 - pad - chipH / 2),
    deltaF: r(deltaF), deltaY: chips ? r(h / 2 - pad - chipH / 2) : r(h / 2 - pad - deltaF * 0.65),
  }
}

// The life's font size: as big as its zone allows, smaller for three digits.
export const numberSize = (p: Parts, text: string) => r(Math.max(12, Math.min(p.numMax, p.numW / (0.66 * Math.max(2, text.length)))))

