import { get, onEvent } from './app'
import { layout } from './board'
import {
  addDelta, changeLife, describeRoll, isTurned, LIMIT, newGame, nextDeltaEnd, noDeltas, playerNames, readGame, roll,
  rollTotal, shownDelta,
} from './logic'

// The tree get() returns, with its components run, and the elements in it
// that match.
function expand(node) {
  if (Array.isArray(node)) return node.map(expand)
  if (!node || typeof node !== 'object') return node
  if (typeof node.type === 'function') return expand(node.type(node.props || {}))
  const children = node.props ? node.props.children : undefined
  return { type: node.type, props: { ...(node.props || {}), children: children === undefined ? undefined : expand(children) } }
}
function findAll(node, match, out = []) {
  if (Array.isArray(node)) {
    node.forEach((n) => findAll(n, match, out))
    return out
  }
  if (!node || typeof node !== 'object') return out
  if (match(node)) out.push(node)
  if (node.props) findAll(node.props.children, match, out)
  return out
}
const titled = (tree, title) => findAll(tree, (n) => n.props && n.props.title === title)[0]
const leftOf = (el) => Number(/left-\[(-?\d+)px\]/.exec(el.props.className)[1])
const words = (node) => {
  if (node === null || node === undefined || typeof node === 'boolean') return ''
  if (typeof node === 'string' || typeof node === 'number') return String(node)
  if (Array.isArray(node)) return node.map(words).join('')
  return words(node.props ? node.props.children : '')
}
const buttonSaying = (tree, text) => findAll(tree, (n) => n.props && typeof n.props.onClick === 'function' && words(n) === text)[0]

function at<T>(when: number, run: () => T): T {
  const real = Date.now
  Date.now = () => when
  try {
    return run()
  } finally {
    Date.now = real
  }
}
const T0 = 1_800_000_000_000

const render = (app) => expand(get(app, makeContext()))

describe('counting', () => {
  it('changes one player by one or five, within the limit', () => {
    let game = newGame(20)
    game = changeLife(game, 1, -1)
    game = changeLife(game, 1, -5)
    game = changeLife(game, 0, 5)
    expect(game.life).toEqual([25, 14, 20, 20])
    expect(changeLife(newGame(LIMIT), 0, 1).life[0]).toBe(LIMIT)
    expect(changeLife(newGame(-LIMIT), 0, -1).life[0]).toBe(-LIMIT)
    expect(changeLife(game, 7, 1)).toBe(game)
  })

  it('adds up the change until a pause, and shows it until the pause is over', () => {
    let d = noDeltas()
    d = addDelta(d, 0, -1, T0, 3000)
    d = addDelta(d, 0, -1, T0 + 1000, 3000)
    d = addDelta(d, 0, -1, T0 + 2500, 3000)
    expect(shownDelta(d, 0, T0 + 2600, 3000)).toBe(-3)
    expect(nextDeltaEnd(d, T0 + 2600, 3000, 2)).toBe(2.9)
    // After the pause it is gone, and the next tap starts again.
    expect(shownDelta(d, 0, T0 + 5600, 3000)).toBe(0)
    expect(nextDeltaEnd(d, T0 + 5600, 3000, 2)).toBe(-1)
    d = addDelta(d, 0, 5, T0 + 9000, 3000)
    expect(shownDelta(d, 0, T0 + 9000, 3000)).toBe(5)
  })

  it('counts a tap on a half, keeps it in the state, and shows the change', () => {
    const app = makeApp({ state: { players: '2', startingLife: '20', facing: 'upright' } })
    const tree = at(T0, () => render(app))
    at(T0, () => titled(tree, 'Player 2: minus one').props.onClick({}))
    at(T0 + 500, () => titled(tree, 'Player 2: minus one').props.onClick({}))
    at(T0 + 900, () => titled(tree, 'Player 2: plus five').props.onClick({}))
    expect(app.state.game.life.slice(0, 2)).toEqual([20, 23])
    // The next render shows +3 and wakes the frame when it is due to go.
    const after = at(T0 + 1000, () => render(app))
    expect(words(after)).toContain('+3')
    expect(app.nextSleep).toBeGreaterThan(2.5)
    expect(app.nextSleep).toBeLessThan(3.1)
  })

  it('takes a hold as five where the panel is fast, and leaves holds alone on e-paper', () => {
    const lcd = makeApp({ state: { facing: 'upright' }, frame: { fast: true } })
    const minus = titled(at(T0, () => render(lcd)), 'Player 1: minus one')
    at(T0, () => minus.props.onLongPress({}))
    expect(lcd.state.game.life[0]).toBe(15)
    const paper = makeApp({ state: { facing: 'upright' }, frame: { fast: false, paper: true } })
    expect(titled(at(T0, () => render(paper)), 'Player 1: minus one').props.onLongPress).toBeUndefined()
  })

  it('keeps the game, and starts again when the starting life changes', () => {
    const saved = { start: 20, life: [12, 7, 20, 20], roll: { kind: 'd20', values: [17] } }
    expect(readGame(saved, 20).life).toEqual([12, 7, 20, 20])
    expect(readGame(saved, 40)).toEqual({ start: 40, life: [40, 40, 40, 40], roll: { kind: 'd20', values: [17] } })
    expect(readGame(null, 30).life).toEqual([30, 30, 30, 30])
    expect(readGame({ start: 20, life: ['x', 5000] }, 20).life).toEqual([20, LIMIT, 20, 20])
