})

describe('turning', () => {
  it('turns the top row when the frame lies between the players', () => {
    expect([0, 1].map((i) => isTurned(i, 2, 'across'))).toEqual([true, false])
    expect([0, 1, 2].map((i) => isTurned(i, 3, 'across'))).toEqual([true, false, false])
    expect([0, 1, 2, 3].map((i) => isTurned(i, 4, 'across'))).toEqual([true, true, false, false])
    expect([0, 1, 2, 3].map((i) => isTurned(i, 4, 'upright'))).toEqual([false, false, false, false])
  })

  it('lays the turned row out on top, and everyone side by side when upright on a wide panel', () => {
    const across = layout(800, 480, 2, 'across', false, 1, false)
    expect(across.cells.map((c) => [c.i, c.turned, c.y < 240])).toEqual([[0, true, true], [1, false, false]])
    expect(across.bar.y).toBeGreaterThan(across.cells[0].y + across.cells[0].h)
    expect(across.bar.y + across.bar.h).toBeLessThan(across.cells[1].y)
    const upright = layout(800, 480, 3, 'upright', false, 1, false)
    expect(upright.cells.map((c) => c.y)).toEqual([8, 8, 8])
    expect(upright.cells.every((c) => !c.turned)).toBe(true)
    // Every part fits the panel.
    for (const [W, H, n] of [[800, 480, 4], [480, 800, 3], [240, 320, 4], [1200, 1600, 2]]) {
      for (const c of layout(W, H, n, 'across', false, 1, false).cells) {
        expect(c.x + c.w <= W && c.y + c.h <= H && c.x >= 0 && c.y >= 0).toBe(true)
      }
    }
  })

  it('keeps a round panel\'s lives inside the circle', () => {
    const b = layout(466, 466, 4, 'across', true, 1, false)
    for (const c of b.cells) {
      const corners = [[0, 0], [1, 0], [0, 1], [1, 1]].map(([u, v]) => [c.x + c.inner.x + u * c.inner.w, c.y + c.inner.y + v * c.inner.h])
      for (const [x, y] of corners) expect(Math.hypot(x - 233, y - 233)).toBeLessThan(222)
    }
  })

  it('puts a turned player\'s minus on our right, their left', () => {
    const app = makeApp({ state: { players: '2', facing: 'across' } })
    const tree = at(T0, () => render(app))
    const top = (titled(tree, 'Player 1: minus one'))
    const topPlus = titled(tree, 'Player 1: plus one')
    expect(leftOf(top)).toBeGreaterThan(leftOf(topPlus))
    const bottom = titled(tree, 'Player 2: minus one')
    const bottomPlus = titled(tree, 'Player 2: plus one')
    expect(leftOf(bottom)).toBeLessThan(leftOf(bottomPlus))
    expect(playerNames('Ana, , Cleo', 3)).toEqual(['Ana', 'Player 2', 'Cleo'])
  })
})

describe('dice', () => {
  it('rolls within each die\'s range, at both ends of Math.random', () => {
    const low = () => 0
    const high = () => 0.999999
    expect(roll('d6', low).values).toEqual([1])
    expect(roll('d6', high).values).toEqual([6])
    expect(roll('2d6', low).values).toEqual([1, 1])
    expect(roll('2d6', high).values).toEqual([6, 6])
    expect(roll('d20', low).values).toEqual([1])
    expect(roll('d20', high).values).toEqual([20])
    expect(roll('coin', low).values).toEqual([1])
    expect(roll('coin', high).values).toEqual([2])
    // A random that returns 1 (it never should) still lands on the die.
    expect(roll('d20', () => 1).values).toEqual([20])
  })

  it('stays in range over many rolls', () => {
    const sides = { d6: 6, '2d6': 6, d20: 20, coin: 2 }
    for (const kind of Object.keys(sides)) {
      for (let n = 0; n < 300; n++) {
        for (const v of roll(kind).values) {
          expect(Number.isInteger(v) && v >= 1 && v <= sides[kind]).toBe(true)
        }
      }
    }
  })

  it('says the last roll in the bar, and keeps it', () => {
    expect(describeRoll({ kind: '2d6', values: [3, 5] })).toBe('2d6: 3 + 5 = 8')
    expect(describeRoll({ kind: 'd20', values: [17] })).toBe('d20: 17')
    expect(describeRoll({ kind: 'coin', values: [2] })).toBe('Coin: Tails')
    expect(rollTotal({ kind: '2d6', values: [6, 6] })).toBe(12)
    const app = makeApp({ state: { players: '2' } })
    const board = at(T0, () => render(app))
    at(T0, () => buttonSaying(board, 'Dice').props.onClick({}))
    const card = at(T0, () => render(app))
    at(T0, () => buttonSaying(card, 'd20').props.onClick({}))
    const r = app.state.game.roll
    expect(r.kind).toBe('d20')
    expect(r.values[0] >= 1 && r.values[0] <= 20).toBe(true)
    // An LCD tumbles the die for a moment, drawing again soon, then lands.
    expect(words(at(T0 + 100, () => render(app)))).toContain('Rolling...')
    expect(app.nextSleep).toBe(0.08)
    expect(words(at(T0 + 1000, () => render(app)))).toContain(`d20: ${r.values[0]}`)
    expect(app.state.game.roll).toEqual(r)
  })

  it('shows the roll in one picture on e-paper', () => {
    const app = makeApp({ state: { players: '2' }, frame: { fast: false, paper: true, color: false } })
    at(T0, () => buttonSaying(at(T0, () => render(app)), 'Dice').props.onClick({}))
    at(T0, () => buttonSaying(at(T0, () => render(app)), 'Coin').props.onClick({}))
    const side = app.state.game.roll.values[0] === 1 ? 'Heads' : 'Tails'
    const card = words(at(T0 + 10, () => render(app)))
    expect(card).toContain(side)
    expect(card).not.toContain('Rolling')
  })
})

describe('a new game', () => {
  it('asks first, then puts everyone back to the starting life and keeps the roll', () => {
    const app = makeApp({ state: { players: '3', startingLife: '40', game: { start: 40, life: [31, 12, 40, 40], roll: { kind: 'd6', values: [4] } } } })
    const board = at(T0, () => render(app))
    at(T0, () => buttonSaying(board, 'New game').props.onClick({}))
    const asking = at(T0, () => render(app))
    expect(words(asking)).toContain('Everyone goes back to 40 life.')
    // While it asks, the board takes no taps.
    expect(titled(asking, 'Player 1: minus one')).toBeUndefined()
    at(T0, () => buttonSaying(asking, 'Cancel').props.onClick({}))
    expect(app.state.game.life.slice(0, 3)).toEqual([31, 12, 40])
    at(T0, () => buttonSaying(at(T0, () => render(app)), 'New game').props.onClick({}))
    at(T0, () => buttonSaying(at(T0, () => render(app)), 'New game').props.onClick({}))
    expect(app.state.game).toEqual({ start: 40, life: [40, 40, 40, 40], roll: { kind: 'd6', values: [4] } })
  })

  it('closes on the frame\'s Back, and on Escape', () => {
    const app = makeApp({ state: { players: '2' } })
    at(T0, () => buttonSaying(at(T0, () => render(app)), 'New game').props.onClick({}))
    expect(onEvent(app, { event: 'back', payload: {} })).toBe(true)
    expect(onEvent(app, { event: 'back', payload: {} })).toBe(false)
    expect(onEvent(app, { event: 'keyDown', payload: { key: 'n' } })).toBe(true)
    expect(onEvent(app, { event: 'keyDown', payload: { key: 'Escape' } })).toBe(true)
    expect(titled(at(T0, () => render(app)), 'Player 1: minus one')).toBeDefined()
  })
})

